import json
from fractions import Fraction as F

bps = [-23, 5, 48]

def f(x):
    return abs(x + 23) + abs(x - 5) + abs(x - 48)

def g(x):
    return f(x) - 2 * x

def solutions(k):
    # g is piecewise linear with breakpoints bps; solve on each piece exactly
    sols = set()
    edges = [None] + bps + [None]
    for i in range(len(edges) - 1):
        lo, hi = edges[i], edges[i + 1]
        # choose two sample points inside the piece to get slope/intercept
        if lo is None:
            a, b = F(hi - 2), F(hi - 1)
        elif hi is None:
            a, b = F(lo + 1), F(lo + 2)
        else:
            a, b = F(lo) + F(hi - lo, 3), F(lo) + F(2 * (hi - lo), 3)
        m = (g(b) - g(a)) / (b - a)
        c = g(a) - m * a
        if m == 0:
            continue
        x = (k - c) / m
        if (lo is None or x >= lo) and (hi is None or x <= hi):
            sols.add(x)
    return sols

# For convex g with g -> infinity at both ends, one solution only at the minimum.
cands = {g(F(b)) for b in bps}
good = sorted(k for k in cands if len(solutions(k)) == 1)
total = sum(good)
print(json.dumps({
    "final_answer": str(total),
    "evidence": {"k_values": [str(k) for k in good],
                 "candidates": {str(k): len(solutions(k)) for k in sorted(cands)}}
}))
